if __name__ == '__main__':
    bad = []
    for k, v in FORMS.items():
        assert len(v) == 8, k
        for s in v[1:]:
            items = s.split('; ')
            if not 8 <= len(items) <= 10: bad.append((k, len(items)))
            for i in items:
                if any(c in i for c in ';{}|') or ': ' in i: bad.append((k, i))
    for k, s in SHARED.items():
        items = s.split('; ')
        if not 10 <= len(items) <= 12: bad.append((k, len(items)))
        for i in items:
            if any(c in i for c in ';{}|') or ': ' in i: bad.append((k, i))
    print('forms', len(FORMS), 'shared', {k: len(v.split('; ')) for k, v in SHARED.items()}, 'problems', bad)

